import java.util.*;
public class TextEditing{
    public static int maxLength(String s){
        String tempStr="";
        boolean insideParentheses=false;
        for(int i=0;i<s.length();i++){
            char ch=s.charAt(i);
            if(ch=='(')
                insideParentheses=true;
            else if(ch==')'){
                insideParentheses=false;
                tempStr+="_";
            }
            if(!insideParentheses && ch!=')')
                tempStr+=ch;
        }
        String[] parts=tempStr.split("_");
        int maxLen=0;
        for(String part:parts)
            maxLen=Math.max(maxLen, part.length());
        return maxLen;
    }
    public static int count(String s){
        String[] parts=s.split("_");
        int count=0;
        for(String p:parts)
            if(p.length()>0)
                count++;
        return count;
    }
    public static int words(String s){
        int total=0;
        StringBuilder current=new StringBuilder();
        boolean inParent=false;
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(c=='(')
                inParent=true;
            else if(c==')'){
                inParent=false;
                total+=count(current.toString());
                current.setLength(0);
            }
            if(inParent && c!='(')
                current.append(c);
        }
        return total;
    }
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        String s=sc.next();
        System.out.println(maxLength(s)+" "+words(s));
    }
}
